const row = $input.last().json;

const planKey = Object.keys(row).find(
  key => key.trim().toLocaleLowerCase("de-DE") === "wochenplan"
);

if (!planKey) {
  throw new Error(
    `wochenplan row doesn't exist` +
    `rows: ${Object.keys(row).join(", ")}`
  );
}

const rawPlan = String(row[planKey] ?? "");

const lines = rawPlan
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

if (lines.length === 0) {
  throw new Error("The field was empty.");
}

const parts = new Intl.DateTimeFormat("en-US", {
  timeZone: "Europe/Berlin",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
}).formatToParts(new Date());

const dateParts = Object.fromEntries(
  parts.map(part => [part.type, part.value])
);

const today = `${dateParts.year}-${dateParts.month}-${dateParts.day}`;
const todayDate = new Date(`${today}T12:00:00.000Z`);
const todayWeekday = todayDate.getUTCDay();

function normalizeDay(value) {
  return value
    .trim()
    .replace(/\.$/, "")
    .toLocaleLowerCase("hu-HU")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

const tasks = lines.map((line, index) => {
  // Az utolsó " - " választja el a feladatot a nap nevétől.
  const separator = line.lastIndexOf(" - ");

  if (separator === -1) {
    throw new Error(
      `A(z) ${index + 1}. sor hibás: "${line}". ` +
      `Elvárt formátum: Feladat - Nap`
    );
  }

  const rawTask = line.slice(0, separator).trim();
  const rawDay = line.slice(separator + 3).trim();
  const parsedDay = dayMap[normalizeDay(rawDay)];

  if (!rawTask || !parsedDay) {
    throw new Error(
      `A(z) ${index + 1}. sorban hibás a feladat vagy a nap: "${line}"`
    );
  }

  // A nap legközelebbi mai vagy jövőbeli előfordulása.
  const offset =
    (parsedDay.weekday - todayWeekday + 7) % 7;

  const due = new Date(todayDate.getTime());
  due.setUTCDate(due.getUTCDate() + offset);

  return {
    raw_task: rawTask,
    day: parsedDay.day,
    due_date: due.toISOString().slice(0, 10),
  };
});

return [
  {
    json: {
      submission_date: today,
      tasks,
    },
  },
];

