const response = $input.first().json;

// A Groq válasza ebben a mezőben tartalmazza
// az AI által generált JSON-szöveget.
const content = response.choices?.[0]?.message?.content;

if (typeof content !== "string") {
  throw new Error(
    "Nem találom a Groq válaszában a choices[0].message.content mezőt."
  );
}

let parsed;

try {
  parsed = JSON.parse(content);
} catch {
  throw new Error("Az AI válasza nem érvényes JSON.");
}

if (!Array.isArray(parsed.tasks)) {
  throw new Error("Az AI válaszából hiányzik a tasks tömb.");
}

const allowedCategories = [
  "Russisch lernen",
  "TUM",
  "Arbeit",
  "Training",
  "Sonstiges"
];

return parsed.tasks.map((task, index) => {
  const title = String(task.title ?? "").trim();
  const description = String(task.description ?? "").trim();
  const dueDate = String(task.due_date ?? "").trim();
  const category = String(task.category ?? "").trim();

  if (!title) {
    throw new Error(`A(z) ${index + 1}. feladatnak nincs címe.`);
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) {
    throw new Error(
      `Érvénytelen dátum a(z) ${index + 1}. feladatnál: ${dueDate}`
    );
  }

  if (!allowedCategories.includes(category)) {
    throw new Error(
      `Ismeretlen kategória a(z) ${index + 1}. feladatnál: ${category}`
    );
  }

  return {
    json: {
      title,
      description,
      due_date: dueDate,
      category,
    },
  };
});

// 1. Beolvassuk az AI által feldolgozott feladatokat.
const taskItems = $("Parse AI JSON").all().map(item => item.json);

// 2. Segédfüggvény: kezeli az API-válaszok különböző alakjait.
function extractRecords(items) {
  const records = [];

  for (const item of items) {
    const data = item.json;

    if (Array.isArray(data)) {
      records.push(...data);
    } else if (Array.isArray(data.results)) {
      records.push(...data.results);
    } else if (Array.isArray(data.projects)) {
      records.push(...data.projects);
    } else if (Array.isArray(data.sections)) {
      records.push(...data.sections);
    } else if (Array.isArray(data.data)) {
      records.push(...data.data);
    } else if (Array.isArray(data.body?.results)) {
      records.push(...data.body.results);
    } else if (data.id) {
      records.push(data);
    }
  }

  return records;
}

// 3. Lekérjük a másik node-ok tényleges kimenetét.
const projects = extractRecords($("Get Projects").all());
const sections = extractRecords($("Get Sections").all());



// Kis- és nagybetűtől, ékezetektől és írásjelektől független névegyezés.
function normalizeName(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
}

// 4. Kikeressük a célprojektet.
const targetProjectName = "Weekly Plan";

// Ha tesztprojektbe írsz, a fenti nevet cseréld
// például "Weekly Plan Test"-re.
const project = projects.find(
  item => normalizeName(item.name) === normalizeName(targetProjectName)
);

if (!project) {
  throw new Error(
    `Nem találom a(z) "${targetProjectName}" projektet. ` +
    `A lekért projektek: ${projects.map(p => p.name).join(", ")}`
  );
}

// 5. Csak a célprojekthez tartozó szekciókat használjuk.
const projectSections = sections.filter(
  section => String(section.project_id) === String(project.id)
);

if (projectSections.length === 0) {
  throw new Error(
    `A Get Sections nem adott vissza szekciót a Weekly Plan projekthez. ` +
    `Projekt ID: ${project.id}. ` +
    `Lekért szekciók: ${sections.map(
      s => `${s.name} (project_id=${s.project_id})`
    ).join(", ")}`
  );
}

// Kategóriából szekciót keresünk.
function findSection(category) {
  return projectSections.find(
    section => normalizeName(section.name) === normalizeName(category)
  );
}

// 6. Ellenőrizzük és átalakítjuk a feladatokat.
const allowedCategories = [
  "Russisch lernen",
  "TUM",
  "Arbeit",
  "Training",
  "Sonstiges"
];

if (taskItems.length === 0) {
  throw new Error("Az AI nem adott vissza feladatokat.");
}

return taskItems.map((task, index) => {
  const title = String(task.title ?? "").trim();
  const description = String(task.description ?? "").trim();
  const dueDate = String(task.due_date ?? "").trim();

  let category = String(task.category ?? "").trim();

  if (!title) {
    throw new Error(`A(z) ${index + 1}. feladat címe üres.`);
  }

  // A formátum mellett a naptári dátumot is ellenőrizzük.
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) {
    throw new Error(
      `Hibás dátum a(z) ${index + 1}. feladatnál: ${dueDate}`
    );
  }

  const date = new Date(`${dueDate}T12:00:00Z`);

  if (
    Number.isNaN(date.getTime()) ||
    date.toISOString().slice(0, 10) !== dueDate
  ) {
    throw new Error(`Nem létező dátum: ${dueDate}`);
  }

  // Ismeretlen kategória esetén biztonságos tartalék.
  if (!allowedCategories.includes(category)) {
    category = "Needs Review";
  }

  const section = findSection(category);

  if (!section) {
    throw new Error(
      `Nem találom a "${category}" szekciót ` +
      `a(z) "${targetProjectName}" projektben.`
    );
  }

  return {
    json: {
      content: title,
      description,
      due_date: dueDate,
      project_id: project.id,
      section_id: section.id,
    },
  };
});
